package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforcePayPlanEstimateController;import com.rpb.reservation.workforce.payroll.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.workforce.domain.WorkforceException;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforcePayPlanEstimateApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);PayPlanEstimateService service=mock(PayPlanEstimateService.class);String path="/api/v1/stores/"+UUID.randomUUID()+"/workforce/pay-plan-estimate";
 @Test void unauthenticatedEstimateCannotReadSalary()throws Exception{when(actors.currentActor()).thenReturn(Optional.empty());MockMvcBuilders.standaloneSetup(new WorkforcePayPlanEstimateController(actors,service)).build().perform(post(path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));verifyNoInteractions(service);}
 @Test void payrollDenialsStayPrivate()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));when(service.estimate(any(),any(),any())).thenThrow(WorkforceException.forbidden());MockMvcBuilders.standaloneSetup(new WorkforcePayPlanEstimateController(actors,service)).build().perform(post(path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isForbidden()).andExpect(header().string("Cache-Control","private, no-store"));}
}
